INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(39611, 'Joshua 16:10', 'Joshua', 16, 10, 'خو هغوی کنعانیان چې د جازر اوسېدونکي وو، ونه شړل. نو کنعانیان تر نن ورځې پورې د افرایمیانو په منځ کې اوسیږي، خو هغوی مجبور دي چې د غلامانو په توګه کار وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua16_verse_10.mp3', '', 1761754199, 1761754199),
(39612, 'Psalms 42:1', 'Psalms', 42, 1, 'لکه هوسۍ وي په ارمان کې د ویالو د اوبو داسې ای خدایه، یمه ستا په ارمان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms42_verse_1.mp3', '', 1761754199, 1761754199),
(39613, 'Psalms 42:2', 'Psalms', 42, 2, 'ای ژوندی خدایه، زه د ستا د دیدار تږی یمه کله به درشم ستا حضور کې عبادت به وکړم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms42_verse_2.mp3', '', 1761754199, 1761754199),
(39614, 'Psalms 42:3', 'Psalms', 42, 3, 'شپه او ورځ ژاړمه زه اوښکې دي خوراک زما دښمنان تل راته پېغور راکوي چې «د ستا خدای چېرې دی؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms42_verse_3.mp3', '', 1761754199, 1761754199),
(39615, 'Psalms 42:4', 'Psalms', 42, 4, 'زړه مې رامات شي چې رایاد کړم هغه تېر وختونه چې د خدای کور ته به ورتلم له ګڼو خلکو سره وو به خوشحال د شکرانې سندرې مونږ به ویلې د دوی په مخکې به روان ومه زه داسې یوه ګڼه چې نیوه به یې جشن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms42_verse_4.mp3', '', 1761754199, 1761754199),
(39616, 'Psalms 42:5', 'Psalms', 42, 5, 'ای زما ځانه، دومره خفه ولې یم؟ دومره پرېشان ولې یم؟ باید په خدای باندې توکل ولرم یوځل بیا به یې ثنا ووایم ای زما خدایه، خلاصوونکیه زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms42_verse_5.mp3', '', 1761754199, 1761754199),
(39617, 'Psalms 42:6', 'Psalms', 42, 6, 'زما زړګی ماتیږي نو ځکه تاته یمه لاس په دعا په داسې حال کې چې زه دلته راګېر شوی یمه یعنې چې سیند د اردن اخلي سرچینه له دې ځای دعا کوم دلته د غره له حرمون د میسعر له غره نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms42_verse_6.mp3', '', 1761754199, 1761754199),
(39618, 'Psalms 42:7', 'Psalms', 42, 7, 'ستا پارېدلې څپې ما باندې واوختلې لکه یو قهرېدلی دریاب یا غړمبېدونکی ابشار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms42_verse_7.mp3', '', 1761754199, 1761754199),
(39619, 'Psalms 42:8', 'Psalms', 42, 8, 'څښتن د ورځې راسره ښایي تلپاتې مینه زه ورته وایمه د شپې سندرې دعا کومه خدای ته زه چې یې ژوندون راکړی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms42_verse_8.mp3', '', 1761754199, 1761754199),
(39620, 'Psalms 42:9', 'Psalms', 42, 9, 'زه هغه خدای ته چې ساتونکی مې دی داسې وایم: «زه دې ولې یم هېر کړی د خپل دښمن له ظلمه ولې زه ویر کې یمه؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms42_verse_9.mp3', '', 1761754199, 1761754199),
(39621, 'Psalms 42:10', 'Psalms', 42, 10, 'ان هډوکي مې ماتیږي چې دښمن راته پېغور کړي تل دوی وایي ماته داسې: چې «ستا خدای چېرې دی؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms42_verse_10.mp3', '', 1761754199, 1761754199),
(39622, 'Psalms 42:11', 'Psalms', 42, 11, 'ای زما ځانه، دومره خفه ولې یم؟ دومره پرېشان ولې یم؟ باید په خدای باندې توکل ولرم یوځلې بیا به یې ثنا ووایم ای زما خدایه، خلاصوونکیه زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms42_verse_11.mp3', '', 1761754199, 1761754199),
(39623, 'Joshua 21:3', 'Joshua', 21, 3, 'نو څنګه چې څښتن حکم کړی ؤ، د اسراییلو قوم لاویانو ته د خپلو سیمو څخه ځینې ښارګوټي او څړځایونه ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_3.mp3', '', 1761754199, 1761754199),
(39624, 'Joshua 21:4', 'Joshua', 21, 4, 'لومړنۍ پچه د قهاتیانو د طایفو په نوم ووتله. هغو لاویانو ته چې د هارون کاهن د اولادې څخه وو، هغوی ته د یهودا، شمعون او بنیامین د سیمو څخه دیارلس ښارګوټي ورکړل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_4.mp3', '', 1761754199, 1761754199),
(39625, 'Joshua 21:5', 'Joshua', 21, 5, 'د افرایم، دان او لوېدیځې منسي د سیمو څخه لس ښارګوټي د قهات پاتې اولادې ته ورکړل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_5.mp3', '', 1761754199, 1761754199),
(39626, 'Joshua 21:6', 'Joshua', 21, 6, 'د یساکار، اشیر، نفتالي او په باشان کې د ختیځې منسي د سیمو څخه د جرشون اولادې ته دیارلس ښارګوټي ورکړل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_6.mp3', '', 1761754199, 1761754199),
(39627, 'Joshua 21:7', 'Joshua', 21, 7, 'د مراري د اولادې طایفو د روبین، جاد او زبولون د سیمو څخه دولس ښارګوټي تر لاسه کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_7.mp3', '', 1761754199, 1761754199),
(39628, 'Joshua 21:8', 'Joshua', 21, 8, 'نو لکه څنګه چې څښتن د موسی په وسیله امر کړی ؤ، د اسراییلو قوم د پچې له مخې لاویانو ته دا ښارګوټي د څړځایونو سره ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_8.mp3', '', 1761754199, 1761754199),
(39629, 'Joshua 21:11', 'Joshua', 21, 11, 'هغوی ته یې د یهودا په غرنۍ سیمه کې قریت اربع (حبرون) د شاوخوا څړځایونو سره ورکړه (اربع د عناق پلار ؤ).', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_11.mp3', '', 1761754199, 1761754199),
(39630, 'Joshua 21:12', 'Joshua', 21, 12, 'خو هغوی د ښار شاوخوا پټي او کلي پخوا د یفنه زوی کالیب ته د هغه د ملکیت په توګه ورکړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_12.mp3', '', 1761754199, 1761754199),
(39631, 'Joshua 21:13', 'Joshua', 21, 13, 'نو هغوی د هارون کاهن اولادې ته دا لاندې ښارګوټي ورکړل: حبرون (چې په قتل باندې تورن شوي کس دپاره د پناه اخیستلو ښار ؤ)، لبنه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_13.mp3', '', 1761754199, 1761754199),
(39632, 'Joshua 21:14', 'Joshua', 21, 14, 'یتیر، اشتموع،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_14.mp3', '', 1761754199, 1761754199),
(39633, 'Joshua 21:15', 'Joshua', 21, 15, 'حولون، دبیر،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_15.mp3', '', 1761754199, 1761754199),
(39634, 'Joshua 21:16', 'Joshua', 21, 16, 'عین، یوطه او بیت شمس د هغو د څړځایونو سره - د یهودا او شمعون د قبیلو څخه نهه ښارګوټي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_16.mp3', '', 1761754199, 1761754199),
(39635, 'Joshua 21:17', 'Joshua', 21, 17, 'د بنیامین د سیمې څخه یې هغوی ته جبعون، جبع،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_17.mp3', '', 1761754199, 1761754199),
(39636, 'Joshua 21:18', 'Joshua', 21, 18, 'عناتوت او علمون د هغو د څړځایونو سره ورکړل. دا څلور ښارګوټي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_18.mp3', '', 1761754199, 1761754199),
(39637, 'Joshua 21:19', 'Joshua', 21, 19, 'د کاهنانو یعنې د هارون د اولادې دپاره د څړځایونو سره ټول دیارلس ښارګوټي ورکړل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_19.mp3', '', 1761754199, 1761754199),
(39638, 'Joshua 21:20', 'Joshua', 21, 20, 'د لاویانو د قهاتیانو پاتې طایفو ته د افرایم د سیمې څخه یو څو ښارګوټي ورکړل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_20.mp3', '', 1761754199, 1761754199),
(39639, 'Joshua 21:21', 'Joshua', 21, 21, 'هغوی ته د افرایم په غرنۍ سیمه کې دا څلور ښارګوټي ورکړل شول: شکیم (چې په قتل باندې تورن شوي کس دپاره د پناه اخیستلو ښار ؤ)، جازر،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_21.mp3', '', 1761754199, 1761754199),
(39640, 'Joshua 21:22', 'Joshua', 21, 22, 'قبصایم او بیت حورون د هغو د څړځایونو سره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_22.mp3', '', 1761754199, 1761754199),
(39641, 'Joshua 21:23', 'Joshua', 21, 23, 'همدارنګه هغوی د دان د سیمې څخه دا څلور ښارګوټي تر لاسه کړل: التقي، جبتون،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_23.mp3', '', 1761754199, 1761754199),
(39642, 'Joshua 21:24', 'Joshua', 21, 24, 'ایالون او جت رمون د هغو د څړځایونو سره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_24.mp3', '', 1761754199, 1761754199),
(39643, 'Joshua 21:25', 'Joshua', 21, 25, 'هغوی د لوېدیځې نیمې منسي د سیمې څخه دوه ښارګوټي تر لاسه کړل: تعنک او جت رمون د هغو د څړځایونو سره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_25.mp3', '', 1761754199, 1761754199),
(39644, 'Joshua 21:26', 'Joshua', 21, 26, 'دا ټول لس ښارګوټي د هغو د څړځایونو سره د قهاتیانو پاتې طایفو ته ورکړل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_26.mp3', '', 1761754199, 1761754199),
(39645, 'Joshua 21:27', 'Joshua', 21, 27, 'د لاویانو د جرشونیانو طایفو ته لاندېني ښارګوټي ورکړل شول: د ختیځې نیمې منسي د سیمې څخه جولان چې په باشان کې ؤ (چې په قتل باندې تورن شوي کس دپاره د پناه اخیستلو ښار ؤ) او بعشتره د هغو د څړځایونو سره - دوه ښارګوټي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_27.mp3', '', 1761754199, 1761754199),
(39646, 'Joshua 21:28', 'Joshua', 21, 28, 'د یساکار د سیمې څخه قشیون، دابره،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_28.mp3', '', 1761754199, 1761754199),
(39647, 'Joshua 21:29', 'Joshua', 21, 29, 'یرموت او عین جنیم د هغو د څړځایونو سره - څلور ښارګوټي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_29.mp3', '', 1761754199, 1761754199),
(39648, 'Joshua 21:30', 'Joshua', 21, 30, 'د اشیر د سیمې څخه مشال، عبدون،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_30.mp3', '', 1761754199, 1761754199),
(39649, 'Joshua 21:31', 'Joshua', 21, 31, 'حلقات او رحوب د هغو د څړځایونو سره - څلور ښارګوټي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_31.mp3', '', 1761754199, 1761754199),
(39650, 'Joshua 21:32', 'Joshua', 21, 32, 'د نفتالي د سیمې څخه قادش په جلیل کې (چې په قتل باندې تورن شوي کس دپاره د پناه اخیستلو ښار ؤ)، حموت دور او قرتان د هغو د څړځایونو سره - درې ښارګوټي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_32.mp3', '', 1761754199, 1761754199),
(39651, 'Joshua 21:33', 'Joshua', 21, 33, 'د جرشونیانو د طایفو ټول ښارګوټي د هغو د څړځایونو سره دیارلسو ته رسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_33.mp3', '', 1761754199, 1761754199),
(39652, 'Joshua 21:34', 'Joshua', 21, 34, 'د مراریانو طایفو (پاتې لاویانو) ته لاندېني ښارګوټي ورکړل شول: د زبولون د سیمې څخه یقنعام، قرته،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_34.mp3', '', 1761754199, 1761754199),
(39653, 'Joshua 21:35', 'Joshua', 21, 35, 'دمنه او نحلال د هغو د څړځایونو سره - څلور ښارګوټي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_35.mp3', '', 1761754199, 1761754199),
(39654, 'Joshua 21:36', 'Joshua', 21, 36, 'د روبین د سیمې څخه باصر، یاهص،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_36.mp3', '', 1761754199, 1761754199),
(39655, 'Joshua 21:37', 'Joshua', 21, 37, 'قدیموت او میفعه د هغو د څړځایونو سره - څلور ښارګوټي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_37.mp3', '', 1761754199, 1761754199),
(39656, 'Joshua 21:38', 'Joshua', 21, 38, 'د جاد د سیمې څخه راموت په جلعاد کې (چې په قتل باندې تورن شوي کس دپاره د پناه اخیستلو ښار ؤ)، محنایم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_38.mp3', '', 1761754199, 1761754199),
(39657, 'Joshua 21:39', 'Joshua', 21, 39, 'حشبون او یعزیر د هغو د څړځایونو سره - ټول څلور ښارګوټي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_39.mp3', '', 1761754199, 1761754199),
(39658, 'Joshua 21:40', 'Joshua', 21, 40, 'د ټولو ښارګوټو شمېر چې د مراریانو طایفو یعنې پاتې لاویانو ته ورکړل شول، دولسو ته رسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_40.mp3', '', 1761754199, 1761754199),
(39659, 'Joshua 21:43', 'Joshua', 21, 43, 'نو څښتن اسراییلو ته هغه ټوله ځمکه ورکړه چې د هغوی د نیکونو سره یې قسم خوړلی ؤ. هغوی د دې ځمکې ملکیت تر لاسه کړ او هلته ځای په ځای شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_43.mp3', '', 1761754199, 1761754199),
(39660, 'Joshua 21:44', 'Joshua', 21, 44, 'لکه څنګه چې څښتن د هغوی د نیکونو سره وعده کړې وه، هغه د هغوی په ټوله خاوره کې ارامي راوستله. د هغوی یو دښمن هم نه شو کولای چې د هغوی په وړاندې ودریږي، ځکه چې څښتن اسراییلیانو ته په خپلو ټولو دښمنانو باندې بری ورکړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_44.mp3', '', 1761754199, 1761754199),
(39661, 'Joshua 21:45', 'Joshua', 21, 45, 'څښتن چې کومې وعدې د اسراییلو د قوم سره کړې وې، هغه ټولې یې سرته ورسولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua21_verse_45.mp3', '', 1761754199, 1761754199),
(39662, 'Jeremiah 17:1', 'Jeremiah', 17, 1, 'مالِک خُدائ فرمائى چې، ”د يهوداه د خلقو ګناه د اوسپنې په قلم چې نوکه يې د هيرې ده، ستاسو د کاڼو نه په سختو زړُونو نقش شوې ده او ستاسو د قربان‌ګاه په ګوټونو ليکلې شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_1.mp3', '', 1761754199, 1761754199),
(39663, 'Jeremiah 17:2', 'Jeremiah', 17, 2, 'نۀ صرف تاسو بلکې ستاسو بچى هم خپلې قربان‌ګاه او د اشيرې بُت شکلونه همېشه رايادوى کۀ د شنې ونې په خوا کښې وى او کۀ په اوچته غونډۍ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_2.mp3', '', 1761754199, 1761754199),
(39664, 'Jeremiah 17:3', 'Jeremiah', 17, 3, 'نو زۀ به په دې مُلک کښې خپل مقدس غر سره ستاسو د ټول مال دولت او ستاسو علاقائى عبادتخانې نورو خلقو ته د غنيمت په توګه حواله کړم، دا ستاسو د ګناهونو بدل دے کوم چې تاسو په خپل ټول مُلک کښې کړې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_3.mp3', '', 1761754199, 1761754199),
(39665, 'Jeremiah 17:4', 'Jeremiah', 17, 4, 'ستاسو د خپلې ګناه په وجه به هغه مُلک ستاسو د لاس نه ووځى کوم چې ما تاسو ته په ميراث کښې درکړے دے. زۀ به تاسو په هغه مُلکونو کښې چې تاسو يې نۀ پېژنئ دشمنانو ته د غلام په شکل حواله کړم. ځکه چې تاسو زما د غصې اور بل کړے دے او هغه به تل بليږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_4.mp3', '', 1761754199, 1761754199),
(39666, 'Jeremiah 17:5', 'Jeremiah', 17, 5, 'مالِک خُدائ فرمائى چې، ”لعنت دې په هغه چا وى چې د هغۀ زړۀ د مالِک خُدائ نه اوړېدلے وى او په فانى انسان توکل او د هغۀ په زور بهروسه کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_5.mp3', '', 1761754199, 1761754199),
(39667, 'Jeremiah 17:6', 'Jeremiah', 17, 6, 'هغه د بيابان د هغه بوټى په شان دے، کۀ څۀ هم چې خير وى خو هغوئ ته به مِلاو نۀ شى. ځکه چې هغه به د بيابان په خشکه او مالګينه زمکه کښې شوے وى، چرته چې نور څۀ نۀ کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_6.mp3', '', 1761754199, 1761754199),
(39668, 'Jeremiah 17:7', 'Jeremiah', 17, 7, 'خو بختور دى هغوئ څوک چې په مالِک خُدائ يقين لرى، او په مالِک خُدائ يې توکل کړے وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_7.mp3', '', 1761754199, 1761754199),
(39669, 'Jeremiah 17:8', 'Jeremiah', 17, 8, 'هغوئ د هغه ونو په شان دى چې د لختى په غاړه کَرلے شوې وى او جرړې يې اوبو ته رسېدلې وى. نو کله چې د ګرمۍ موسم راشى نو يره يې نۀ وى، د هغوئ پاڼې هر وخت شنې وى. او په خُشک سالۍ کښې يې څۀ پرېشانى نۀ وى، نو کله هم بې‌مېوې نۀ پاتې کيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_8.mp3', '', 1761754199, 1761754199),
(39670, 'Jeremiah 17:9', 'Jeremiah', 17, 9, 'د انسان زړۀ د هر څۀ نه زيات دوکه مار وى، او د شرارت نه ډک وى. څوک پرې هم نۀ پوهيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_9.mp3', '', 1761754199, 1761754199),
(39671, 'Jeremiah 17:10', 'Jeremiah', 17, 10, '”زۀ مالِک خُدائ د انسان د زړۀ لټون کوم او د هغۀ پټ سوچونه آزمائيم، زۀ هر چا ته اجر د هغۀ د عمل په مطابق ورکوم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_10.mp3', '', 1761754199, 1761754199),
(39672, 'Jeremiah 17:11', 'Jeremiah', 17, 11, 'هغه څوک چې په ناجائزه طريقې سره مال دولت راجمع کړى هغه د هغه تيتر په شان وى چې پردۍ هګۍ وشاربى کومې چې هغې اچولې نۀ وى، نو وروستو به د هغۀ نه ټول مال دولت لاړ شى، کله چې د هغۀ عمر نيم تېر شى نو د هغۀ مال دولت به د هغۀ نه والوځى او په آخر کښې به دے خپل ځان کم عقل ثابت کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_11.mp3', '', 1761754199, 1761754199),
(39673, 'Jeremiah 17:12', 'Jeremiah', 17, 12, 'خو هغه جلالى تخت چې د ازل نه اوچت دے، هغه زمونږ د خُدائ پاک مقدس کور دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_12.mp3', '', 1761754199, 1761754199),
(39674, 'Jeremiah 17:13', 'Jeremiah', 17, 13, 'اے مالِکه خُدايه، د بنى اِسرائيلو اُميده، هر څوک چې تا نه مخ واړوى هغوئ ټول به ټيټ سترګې او شرمنده شى. هغوئ چا چې تا نه مخ اړولے دے په دوړو د ليکلو په شان دى، دوئ به زر ختم شى ځکه چې هغوئ د هغه مالِک خُدائ نه مخ اړولے دے څوک چې د ژوندون د اوبو چينه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_13.mp3', '', 1761754199, 1761754199),
(39675, 'Jeremiah 17:14', 'Jeremiah', 17, 14, 'اے مالِکه خُدايه، کۀ چرې تۀ ما له شفا راکړې نو زۀ به بلکل روغ رمټ شم، کۀ چرې تۀ ما له خلاصون راکړې نو زۀ به بچ شم، ځکه چې زۀ صرف ستا ثناء صِفت کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_14.mp3', '', 1761754199, 1761754199),
(39676, 'Jeremiah 17:15', 'Jeremiah', 17, 15, 'هغوئ ما ته بار بار دا وائى چې، د مالِک خُدائ هغه کارونه څۀ شول د چا د پوره کېدلو په حقله چې هغۀ پېشګوئې کړې وه؟ نو اوس دې هغه پوره کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_15.mp3', '', 1761754199, 1761754199),
(39677, 'Jeremiah 17:16', 'Jeremiah', 17, 16, 'اے مالِکه خُدايه، زۀ د هغه کار نه نۀ يم تښتېدلے د کوم دپاره چې تاسو زۀ د خپل قوم دپاره د شپونکى په حيثيت مقرر کړے يم. تاسو ته پته ده چې ما په هغوئ د افت د ورځې د راتلو خواهش نۀ دے کړے. زما د شونډو نه چې څۀ هم وتلى دى هغه ستا په وړاندې څرګند دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_16.mp3', '', 1761754199, 1761754199),
(39678, 'Jeremiah 17:17', 'Jeremiah', 17, 17, 'مالِکه خُدايه، ما مۀ يروه، د افت په ورځ صرف تۀ زما اُميد يې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_17.mp3', '', 1761754199, 1761754199),
(39679, 'Jeremiah 17:18', 'Jeremiah', 17, 18, 'زما دشمنان دې وشرميږى خو ما مۀ شرموه، په هغوئ يره راوله خو ما مۀ يروه. په هغوئ د افت ورځې راوله، او هغوئ په دوه چنده تباه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_18.mp3', '', 1761754199, 1761754199),
(39680, 'Jeremiah 17:19', 'Jeremiah', 17, 19, 'مالِک خُدائ ما ته وفرمائيل، ”يرمياه، لاړ شه او د عوامى دروازې په خولۀ کښې ودرېږه په کومه چې د يهوداه بادشاهان ځى راځى او هم داسې د يروشلم په نورو دروازو کښې ودرېږه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_19.mp3', '', 1761754199, 1761754199),
(39681, 'Jeremiah 17:20', 'Jeremiah', 17, 20, 'هغوئ ته ووايه، د مالِک خُدائ پېغام واورئ. اے د يهوداه بادشاهانو او د يهوداه ټولو خلقو او د يروشلم اوسېدونکو او هغوئ ټولو ته چې په دې دروازې ځى راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_20.mp3', '', 1761754199, 1761754199),
(39682, 'Jeremiah 17:21', 'Jeremiah', 17, 21, 'مالِک خُدائ فرمائى چې، خبردار چې د سبت په ورځ په خپل سر پنډ مۀ اوچتوئ او د يروشلم په دروازو پنډ سره مۀ ننوځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_21.mp3', '', 1761754199, 1761754199),
(39683, 'Jeremiah 17:22', 'Jeremiah', 17, 22, 'او تر دې چې په خپلو کورونو کښې هم د سبت په ورځ هيڅ قسمه کار مۀ کوئ او مۀ څۀ بار اوچتوئ. خو د سبت ورځ مقدسه وساتئ لکه څنګه چې ما ستاسو پلار نيکۀ ته حکم کړے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_22.mp3', '', 1761754199, 1761754199),
(39684, 'Jeremiah 17:23', 'Jeremiah', 17, 23, 'خو هغوئ ما ته غوږ ونۀ نيولو او نۀ يې ما ته توجو راکړه او نۀ يې زما پيروى وکړه. خو هغوئ سرکشه وُو او اصلاح کولو ته يې جواب ورنۀ کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_23.mp3', '', 1761754199, 1761754199),
(39685, 'Jeremiah 17:24', 'Jeremiah', 17, 24, 'خو مالِک خُدائ فرمائى، کۀ چرې تاسو زما خبره ومنئ او د سبت په ورځ په دې دروازو د تجارت دپاره څۀ داخل نۀ کړئ او نۀ څۀ کار وکړئ، او هغه مقدسه وساتئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_24.mp3', '', 1761754199, 1761754199),
(39686, 'Jeremiah 17:25', 'Jeremiah', 17, 25, 'نو بيا به هغه بادشاهان څوک چې د داؤد په تخت ناست دى نو هغوئ به د خپلو آفسرانو سره د دې ښار په دروازو ځى راځى. او هغوئ او د هغوئ آفسران به په آسونو او ګاډو سوارۀ راشى، او د يهوداه خلق به ورسره وى او هغوئ څوک چې په يروشلم کښې اوسيږى، او دا ښار به د تل دپاره آباد وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_25.mp3', '', 1761754199, 1761754199),
(39687, 'Jeremiah 17:26', 'Jeremiah', 17, 26, 'د يهوداه د ښارونو او د يروشلم د ګېرچاپېره کلو نه به خلق راشى، هغوئ به د بنيامين د علاقې، د مغربى غونډو د لمنو نه، او د نجب او د غريزې علاقې نه به د خپلو سوزېدونکو نذرانو او قربانو سره راشى. هغوئ به د خپلو غلو دانو او خوشبوئى د شکرانې نذرانې سره د مالِک خُدائ کور ته راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_26.mp3', '', 1761754199, 1761754199),
(39688, 'Jeremiah 17:27', 'Jeremiah', 17, 27, 'خو کۀ تاسو زما خبره ونۀ منئ او د سبت ورځ مقدسه ونۀ ساتئ، او لکه د نورو ورځو په شان د سبت په ورځ د سودا پنډونه د يروشلم دروازو ته راؤړئ، نو بيا به زۀ په دې دروازو اور بل کړم. او دا اور به د يروشلم محلونه وسوزوى. او د دې اور لمبې به هيڅوک مړې کولے نۀ شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah17_verse_27.mp3', '', 1761754199, 1761754199),
(39689, 'Jeremiah 20:1', 'Jeremiah', 20, 1, 'کله چې فشحور د اِمير زوئ څوک چې د مالِک خُدائ په کور کښې مشر اِمام وو، هغه څۀ واورېدل د څۀ چې يرمياه پېشګوئې کوله،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_1.mp3', '', 1761754199, 1761754199),
(39690, 'Jeremiah 20:2', 'Jeremiah', 20, 2, 'نو هغۀ يرمياه نبى راګېر کړلو او په کوړو يې ووهلو او بيا يې هغه پاس د مالِک خُدائ په کور کښې د بنيامين په دروازه کښې د لرګى په کُنده کښې بند کړلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_2.mp3', '', 1761754199, 1761754199),
(39691, 'Jeremiah 20:3', 'Jeremiah', 20, 3, 'په بله ورځ کله چې فشحور هغه د کُندې نه آزاد کړو، يرمياه هغۀ ته وفرمائيل چې، ”مالِک خُدائ ستا نوے نوم اېښے دے او د نن نه پس به ستا نوم فشحور نۀ وى بلکې په هر اړخ باندې دهشت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_3.mp3', '', 1761754199, 1761754199),
(39692, 'Jeremiah 20:4', 'Jeremiah', 20, 4, 'ځکه مالِک خُدائ په خپله دا فرمائى چې، زۀ به په تا او ستا په دوستانو باندې دهشت راولم، او تۀ به په خپلو سترګو سره د هغوئ وژل د دشمنانو د لاسه ووينې. زۀ به د يهوداه ټول خلق د بابل بادشاه ته حواله کړم، څوک چې به د هغوئ نه ځينې بابل ته قېديان بوځى او ځينې به په تُوره قتل کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_4.mp3', '', 1761754199, 1761754199),
(39693, 'Jeremiah 20:5', 'Jeremiah', 20, 5, 'زۀ به د دې ښار ټول مال دولت او د هغوئ ټول قيمتى سامانونه او د يهوداه بادشاه خزانې د هغوئ دشمنانو ته حواله کړم. هغوئ به دا لوټ کړى او بابل ته به يې يوسى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_5.mp3', '', 1761754199, 1761754199),
(39694, 'Jeremiah 20:6', 'Jeremiah', 20, 6, 'ترڅو چې ستا خبره ده فشحوره، تۀ او ستا مکمل خاندان به هم ونيولے شى او بابل ته به بوتلے شى. هلته به تاسو او ستا هغه ټول دوستان مړۀ او ښخ شى چا ته به چې تا په دروغو پېشګوئې کوله چې هيڅ پرواه مۀ کوئ خير به شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_6.mp3', '', 1761754199, 1761754199),
(39695, 'Jeremiah 20:7', 'Jeremiah', 20, 7, 'اے مالِکه خُدايه، تا زۀ دوکه کړم، او زۀ دوکه شوم. تاسو زورَور يئ او زۀ دې مغلوب کړم. زۀ اوس ټوله ورځ د مسخرو شوم، او هر څوک ما پورې ټوقې او خندا کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_7.mp3', '', 1761754199, 1761754199),
(39696, 'Jeremiah 20:8', 'Jeremiah', 20, 8, 'کله چې هم زۀ خپله خولۀ خلاصوم، نو بيا ضرور زۀ د ظلم او تباهۍ په حقله چغې سورې وهم. ځکه چې زۀ د مالِک خُدائ د کلام په وجه ټوله ورځ کنځل او بدې ردې تېروم او سپکولے شم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_8.mp3', '', 1761754199, 1761754199),
(39697, 'Jeremiah 20:9', 'Jeremiah', 20, 9, 'خو چې کله زۀ ووايم چې، ”زۀ به د مالِک خُدائ په حقله خبرې نۀ کوم او نۀ به نور د هغۀ پېغام چا ته رسوم،“ نو بيا د هغۀ کلام زما په زړۀ کښې لکه د اور په شان بليږى او هغه اور زما هډوکو ته رسيږى. زۀ په ځان کښې د هغۀ د ايسارولو د کوشش په وجه ډېر ستړے شوے يم او زۀ هغه نۀ شم ايسارولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_9.mp3', '', 1761754199, 1761754199),
(39698, 'Jeremiah 20:10', 'Jeremiah', 20, 10, 'ما د خپل ځان په حقله د ډېرو خلقو ګونګوسى اورېدلى دى. هغوئ وائى چې، ”هرې خوا ته دهشت دے بس دهشت. راځئ چې د هغۀ اِطلاع ورکړُو. راځئ چې د هغۀ په حقله اِطلاع ورکړُو.“ زما نزدې دوستان هم زما د غورزېدلو په انتظار دى، او هغوئ وائى چې، ”شايد چې هغه دوکه شى، نو بيا به يې راګېر کړُو او د هغۀ نه به خپله بدله واخلو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_10.mp3', '', 1761754199, 1761754199),
(39699, 'Jeremiah 20:11', 'Jeremiah', 20, 11, 'بلکې مالِک خُدائ د يو طاقتور جنګيالى په شان ما سره دے، نو بيا څوک هم چې زما د ژوند ختمولو پسې دى هغوئ به هيڅکله هم کامياب نۀ شى، او په خپله به تيندکونه وخورى. هغوئ به ناکاميابه شى او په شرمونو به وشرميږى، د هغوئ دا بې‌عزتى به هيڅکله د هېرېدلو نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_11.mp3', '', 1761754199, 1761754199),
(39700, 'Jeremiah 20:12', 'Jeremiah', 20, 12, 'خو اے مالِکه خُدايه، ربُ الافواجه، تاسو په خپله صادق سړے وينئ، او تاسو په خپله د انسان د زړۀ او دماغ ژور سوچونه او رازونه آزمايئ. ما خپل خواست تا ته پېش کړے دے نو په دې وجه تاسو زما بدله اخستل ما ته وښايئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_12.mp3', '', 1761754199, 1761754199),
(39701, 'Jeremiah 20:13', 'Jeremiah', 20, 13, 'د مالِک خُدائ حمد ووايئ. د مالِک خُدائ ثناء صِفت ادا کړئ. هغه غريبانان د شريرانو د لاس نه بچ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_13.mp3', '', 1761754199, 1761754199),
(39702, 'Jeremiah 20:14', 'Jeremiah', 20, 14, 'په هغه ورځ دې لعنت وى په کومه چې زۀ پېدا شوے وم. او هغه ورځ دې مبارکه نۀ وى په کومه ورځ چې زۀ د مور نه پېدا شوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_14.mp3', '', 1761754199, 1761754199),
(39703, 'Jeremiah 20:15', 'Jeremiah', 20, 15, 'په هغه کس دې لعنت وى چا چې زما د پلار د خوشحالولو دپاره دا زېرے راوړے وو چې، ”ستا زوئ پېدا شوے دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_15.mp3', '', 1761754199, 1761754199),
(39704, 'Jeremiah 20:16', 'Jeremiah', 20, 16, 'هغه سړے دې د هغه ښارونو په شان شى کوم چې مالِک خُدائ په بې‌رحمۍ سره تباه کړى وُو. هغه دې په سحر کښې د يرې چغې واورى او په غرمه کښې دې د جنګ شور واورى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_16.mp3', '', 1761754199, 1761754199),
(39705, 'Jeremiah 20:17', 'Jeremiah', 20, 17, 'ځکه چې زۀ هغۀ د پېدا کېدو نه وړاندې د مور په ګېډه کښې مړ نۀ کړم، ترڅو چې د هغې ګېډه زما قبر جوړ شوے وے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_17.mp3', '', 1761754199, 1761754199),
(39706, 'Jeremiah 20:18', 'Jeremiah', 20, 18, 'زۀ د مور د خېټې نه ولې دُنيا ته راغلم؟ د دې دپاره پېدا شوم چې په دُنيا کښې تکليفونه او کړاونه وګورم، او چې زما ژوند په بې‌عزتۍ کښې ختم شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah20_verse_18.mp3', '', 1761754199, 1761754199),
(39707, 'Psalms 17:1', 'Psalms', 17, 1, 'واوره زارۍ زما څښتنه، د انصاف دپاره هم د مرستې په خاطر زما فریاد واوره واوره دعا ته زما د بې ریا زړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_1.mp3', '', 1761754199, 1761754199),
(39708, 'Psalms 17:2', 'Psalms', 17, 2, 'زما په حق کې ته انصاف وکړه ځکه پوهېږې حقیقت باندې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_2.mp3', '', 1761754199, 1761754199),
(39709, 'Psalms 17:3', 'Psalms', 17, 3, 'تا امتحان کړ زما زړه ته په شپه کې راغلې ماته زه دې ښه وازمایلم هېڅ بدي دې پیدا نه کړله په ما کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_3.mp3', '', 1761754199, 1761754199),
(39710, 'Psalms 17:4', 'Psalms', 17, 4, 'لکه د نورو په شان نه کوم خبرې بدې ما دی کړی اطاعت د ستا د امر ما د ظلم لاره نه ده خپله کړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_4.mp3', '', 1761754199, 1761754199);